            if not callable(dispatcher):
                raise Problem(_("Unknown command: `%s`.") % escape(command))
            dispatch_kwargs = dict(request.POST.items())
            rv = dispatcher(**dispatch_kwargs)
            if rv:
                return rv
            self.request.method = "GET"
            self.build_form()
