        os.path.abspath(mountpoint).replace(os.sep, ".").lstrip("."),
        tls_port,
    )
def _stunnel_bin():
    installation_message = "Please install it following the instructions at: https://docs.aws.amazon.com/efs/latest/ug/using-amazon-efs-utils.html
    if get_system_release_version() in AMAZON_LINUX_2_RELEASE_VERSIONS:
