                    (self.public_url == other.public_url)
                    and
                    (self.metadata_url == other.metadata_url)
                    and
                    (self.pastie_classname == other.pastie_classname) )
        except Exception as e:
            logger.error("Unable to compare SiteConfig instances: {}".format(e))
            pass
        return res
