def is_authenticated(user, password):
    """Validate credentials.

    Iterate through htpasswd credential file until user matches, extract hash
    (encrypted password) and check hash against user-given password, using the
    method specified in the Radicale config.

    """
    with open(FILENAME) as f:
        for line in f:
            strippedline = line.strip()
            if strippedline:
                login, hash_value = strippedline.split(":")
                if login == user:

                    return _verifuncs[ENCRYPTION](hash_value, password)
    return False

class _ExpiringDict(dict):
    max_age = 0
        now = time.monotonic()
    def _check_age(self, key):
        """Check timestamp for a key"""
        if key not in self.values:

            return
        now = time.monotonic()
        timestamp = self.timestamps[key]
        if self.max_age > 0 and timestamp + self.max_age < now:
            self.values.pop(key)
            self.timestamps.pop(key)
    def __contains__(self, key):
        """dict check for `key in dict`"""
        self._check_age(key)
        return key in self.values
    def __getitem__(self, key):
        """Check age before returning value"""
        self._check_age(key)
        return self.values[key]
    def get(self, key, default=None):
        """dict-like get:"""
        try:
            return self[key]
        except KeyError:
            return default
