def handle_404(exc):
    flask.current_app.logger.debug("Error 404 - Requested URL: {}".format(flask.request.base_url))
    messages = [f"Error {exc.code}: {exc.description}"]
    return render_template('error.html', messages=messages), 404
def handle_error(exc):
    tb = traceback.format_exc()
    try:
        code = exc.code
        desc = exc.desc
    except AttributeError:
        code = 500
        desc = exc

    flask.current_app.logger.debug(exc, exc_info=True)

    messages = [f"Error {code}: {desc}"]
    messages.extend(tb.split('\n'))
    return render_template("error.html", messages=messages), code
ERROR_HANDLERS = [(Exception, handle_error), (404, handle_404)]
def load_config():
    category = flask.request.args.get('category')
    section = flask.request.args.get('section')
    if category not in ("core", "plugin") or not section:
        return jsonify(False), 500

    conf = None
    api = flask.current_app.config["PYLOAD_API"]
    if category == "core":
        conf = api.get_config_dict()
    elif category == "plugin":
        conf = api.get_plugin_config_dict()

    for key, option in conf[section].items():
        if key in ("desc", "outline"):
            continue

        if ";" in option["type"]:
            option["list"] = option["type"].split(";")

    return render_template("settings_item.html", skey=section, section=conf[section])
def rpc(func, args=""):
    api = flask.current_app.config["PYLOAD_API"]

    if flask.request.authorization:
        user = flask.request.authorization.get("username", "")
        password = flask.request.authorization.get("password", "")
    else:
        user = flask.request.form.get("u", "")
        password = flask.request.form.get("p", "")

    if user:
        user_info = api.check_auth(user, password)
        s = set_session(user_info)
    else:
        s = flask.session

    if (
            "role" not in s or
            "perms" not in s or
            not api.is_authorized(func, {"role": s["role"], "permission": s["perms"]})
    ):
        return jsonify({'error': "Unauthorized"}), 401

    args = args.split(",")
    if len(args) == 1 and not args[0]:
        args = []

    kwargs = {}

    for x, y in chain(flask.request.args.items(), flask.request.form.items()):
        if x not in ("u", "p"):
            kwargs[x] = unquote(y)

    try:
        response = call_api(func, *args, **kwargs)
    except Exception as exc:
        response = jsonify(error=str(exc), traceback=traceback.format_exc()), 500

    return response
