            1 if len(log) - perpage + 1 < 1 or perpage == 0 else len(log) - perpage + 1
        )

    if isinstance(fro, datetime.datetime):
        start_line = -1

    data = []
    counter = 0
    perpagecheck = 0
    for logline in log:
        counter += 1

        if counter >= start_line:
            try:
                date, time, level, source, message = _RE_LOGLINE.match(logline).groups()
                dtime = datetime.datetime.strptime(
                    date + " " + time, "%Y-%m-%d %H:%M:%S"
                )
                message = message.strip()
            except (AttributeError, IndexError):
                dtime = None
                date = "?"
                time = " "
                level = "?"
                source = "?"
                message = logline
            if start_line == -1 and dtime is not None and fro <= dtime:
                start_line = counter

            if start_line >= 0:
                data.append(
                    {
                        "line": counter,
                        "date": date + " " + time,
                        "level": level,
                        "source": source,
                        "message": message.rstrip('\n'),
                    }
                )
                perpagecheck += 1
                if (
                    fro is None and dtime is not None
                ):
                    fro = dtime
            if perpagecheck >= perpage > 0:
                break

    if fro is None:
        fro = datetime.datetime.now()

    if reversed:
        data.reverse()

    context = {
        "warning": warning,
        "log": data,
        "from": fro.strftime("%Y-%m-%d %H:%M:%S"),
        "reversed": reversed,
        "perpage": perpage,
        "perpage_p": sorted(perpage_p),
        "iprev": max(start_line - perpage, 1),
