    def _validate_sock_mode(self, proposal):
        value = proposal["value"]
        try:
            converted_value = int(value.encode(), 8)
            assert all(
                (

                    bool(converted_value & stat.S_IRUSR),
                    bool(converted_value & stat.S_IWUSR),

                    converted_value <= 2**12,
